def lb_cactus():
    # 整链一株的产量是 YF*L*L，L=644 时两轮不够目标，第三轮只需前 LAST 格。
    # LAST 比最小解多留 4% 余量：整轮漏收一格就少 32*1287，最小解的余量连一格都不够，
    # 一旦某轮没整块弹开就会掉到目标以下、白跑一整轮。
    cost = get_cost(Entities.Cactus)[Items.Pumpkin]
    tstart(0, 16, [ROUNDS, LAST, cost, num_items(Items.Pumpkin)])
    while num_items(Items.Cactus) < GOAL:
        tstart(0, 16, [1, L0, cost, num_items(Items.Pumpkin)])


def tstart(k, count, arg):
    # 广播式生成32架，父机在子树结束后才返回。
    while count >= 1:
        spawn_drone(tstart, k + count, count // 2, arg)
        count = count // 2
    sp_task(k, arg)


def sp_task(k, arg):
    rounds = arg[0]
    last_len = arg[1]
    cost = arg[2]
    p0 = arg[3]
    if k == 0:
        mine = c0()
    elif k == 1:
        mine = c1()
    elif k == 2:
        mine = c2()
    elif k == 3:
        mine = c3()
    elif k == 4:
        mine = c4()
    elif k == 5:
        mine = c5()
    elif k == 6:
        mine = c6()
    elif k == 7:
        mine = c7()
    elif k == 8:
        mine = c8()
    elif k == 9:
        mine = c9()
    elif k == 10:
        mine = c10()
    elif k == 11:
        mine = c11()
    elif k == 12:
        mine = c12()
    elif k == 13:
        mine = c13()
    elif k == 14:
        mine = c14()
    elif k == 15:
        mine = c15()
    elif k == 16:
        mine = c16()
    elif k == 17:
        mine = c17()
    elif k == 18:
        mine = c18()
    elif k == 19:
        mine = c19()
    elif k == 20:
        mine = c20()
    elif k == 21:
        mine = c21()
    elif k == 22:
        mine = c22()
    elif k == 23:
        mine = c23()
    elif k == 24:
        mine = c24()
    elif k == 25:
        mine = c25()
    elif k == 26:
        mine = c26()
    elif k == 27:
        mine = c27()
    elif k == 28:
        mine = c28()
    elif k == 29:
        mine = c29()
    elif k == 30:
        mine = c30()
    elif k == 31:
        mine = c31()
    base = mine[0]
    cells = mine[1]
    dirs = mine[2]
    cuts = mine[3]
    r = 0
    while r < rounds:
        if r == rounds - 1:
            L = last_len
        else:
            L = L0
        # 末轮沿用整链分段、只截到 L：重新均分会让每架先走位到新地块。
        s = cuts[0]
        e = cuts[1]
        if e > L:
            e = L
        if s < e:
            sp_pass(cells, dirs, base, s, e, r % 2 == 0, L)
            if k == 0:
                # 全部种完后还需等作物成熟，再收走整条链。
                while num_items(Items.Pumpkin) > p0 - cost * L:
                    pass
                tg = get_time() + 1
                while get_time() < tg:
                    pass
                p0 = num_items(Items.Pumpkin)
                harvest()
            else:
                tw = get_time()
                while get_entity_type() != None and get_time() < tw + 4:
                    pass
        r += 1


def sp_pass(cells, dirs, base, s, e, fwd, L):
    # 蛇形相邻格必是山谷-山峰关系，插入时只跟已种好的邻居比一次，序列内才继续往前冒泡。
    if fwd:
        i0 = s
        i1 = e
        st = 1
    else:
        i0 = e - 1
        i1 = s - 1
        st = -1
    go_to(cells[i0 - base] // 32, cells[i0 - base] % 32)
    i = i0
    while i != i1:
        if i != i0:
            move(sp_dir(dirs, base, i - st, i))
        if get_ground_type() != Grounds.Soil:
            till()
        plant(Entities.Cactus)
        j = i
        while j != i0:
            p = j - st
            d = sp_dir(dirs, base, j, p)
            a = measure(d)
            b = measure()
            lo = p
            vlo = a
            vhi = b
            if j < p:
                lo = j
                vlo = b
                vhi = a
            if edge_asc(dirs, base, lo):
                if vlo <= vhi:
                    break
            elif vlo >= vhi:
                break
            swap(d)
            if not is_mid(dirs, base, p):
                break
            move(d)
            j = p
        while j != i:
            move(sp_dir(dirs, base, j, j + st))
            j += st
        i += st
    # 与相邻块交界的边由后种完的一侧补一次交换。
    nb = -1
    if fwd and e < L:
        nb = e
        cur = e - 1
    if not fwd and s > 0:
        nb = s - 1
        cur = s
    if nb >= 0:
        d = sp_dir(dirs, base, cur, nb)
        while measure(d) == None:
            pass
        lo = cur
        vlo = measure()
        vhi = measure(d)
        if nb < cur:
            lo = nb
            vlo = vhi
            vhi = measure()
        if edge_asc(dirs, base, lo) != (vlo <= vhi) and vlo != vhi:
            swap(d)


def sp_dir(dirs, base, a, b):
    # 从 a 格指向 b 格的方向，只在同一条边上来回用。
    if b > a:
        return DIRS[dirs[b - base]]
    return DIRS[(dirs[a - base] + 2) % 4]


def edge_asc(dirs, base, i):
    # 第 i 格到第 i+1 格这条边要求升序（到达方向是北或东）。
    return dirs[i + 1 - base] < 2


def is_mid(dirs, base, i):
    # 第 i 格两侧的边方向相同才算同一条序列内部。
    if i <= 0 or i >= L0 - 1:
        return False
    return (dirs[i + 1 - base] < 2) == (dirs[i - base] < 2)


def go_to(tx, ty):
    dx = (tx - get_pos_x()) % SIZE
    if dx <= SIZE // 2:
        for _ in range(dx):
            move(East)
    else:
        for _ in range(SIZE - dx):
            move(West)
    dy = (ty - get_pos_y()) % SIZE
    if dy <= SIZE // 2:
        for _ in range(dy):
            move(North)
    else:
        for _ in range(SIZE - dy):
            move(South)


if __name__ == "__main__":
    lb_cactus()
